  #(
    parameter DSIZE         = 8,
    parameter ASIZE         = 4,
    parameter FALLTHROUGH   = "FALSE"
    ) (
       input wire              a_clk,
       input wire              a_rst_n,
       input wire              a_winc,
       input wire [DSIZE-1:0]  a_wdata,
       input wire              a_rinc,
       output wire [DSIZE-1:0] a_rdata,
       output wire             a_full,
       output wire             a_afull,
       output wire             a_empty,
       output wire             a_aempty,
       input wire              a_dir,
       input wire              b_clk,
       input wire              b_rst_n,
       input wire              b_winc,
       input wire [DSIZE-1:0]  b_wdata,
       input wire              b_rinc,
       output wire [DSIZE-1:0] b_rdata,
       output wire             b_full,
       output wire             b_afull,
       output wire             b_empty,
       output wire             b_aempty,
       input wire              b_dir,
       output wire             o_ram_a_clk,
       output wire [DSIZE-1:0] o_ram_a_wdata,
       input wire [DSIZE-1:0]  i_ram_a_rdata,
       output wire [ASIZE-1:0] o_ram_a_addr,
       output wire             o_ram_a_rinc,
       output wire             o_ram_a_winc,
       output wire             o_ram_b_clk,
       output wire [DSIZE-1:0] o_ram_b_wdata,
       input wire [DSIZE-1:0]  i_ram_b_rdata,
       output wire [ASIZE-1:0] o_ram_b_addr,
       output wire             o_ram_b_rinc,
       output wire             o_ram_b_winc
       );

  // Internal parameters
  localparam LOG2_SIZE = ASIZE;
  localparam MAX_ENTRIES = 1 << ASIZE;
  localparam GRANT_WIDTH = ASIZE + 1; // Address + Valid bit

  // ---------------------------------------------------------------------------
  // CDC Strategy:
  // 1. Pointers (Write Ptr, Read Ptr, Full Ptr, Empty Ptr) are transferred
  //    across clock domains using a 2-phase handshake (Grant + Ack).
  // 2. The "Grant" signal is a multi-bit snapshot (Address + Valid).
  // 3. The "Ack" signal is a single-bit pulse generated by the receiving domain
  //    when it is ready to accept the new pointer value.
  // 4. This ensures no metastability on the pointer values themselves.
  // 5. Reset release is handled by forcing pointers to 0 and generating a
  //    "reset done" flag that is also crossed safely.
  // ---------------------------------------------------------------------------

  // ---------------------------------------------------------------------------
  // Side A Logic (Clock: a_clk)
  // ---------------------------------------------------------------------------

  // State for pointer transfer to Side B
  reg [GRANT_WIDTH-1:0] a_ptr_to_b;
  reg                   a_ptr_to_b_valid;
  reg                   a_ptr_to_b_ack;

  // State for pointer transfer from Side B
  reg [GRANT_WIDTH-1:0] b_ptr_from_a;
  reg                   b_ptr_from_a_valid;
  reg                   b_ptr_from_a_ack;

  // Reset Done Flags (Crossed)
  reg                   a_rst_done;
  reg                   b_rst_done;

  // Internal Pointers (Local to a_clk)
  reg [ASIZE-1:0]       a_wptr;
  reg [ASIZE-1:0]       a_rptr;
  reg                   a_wptr_valid; // Validity of the pointer currently being sent
  reg                   a_rptr_valid; // Validity of the pointer currently being sent

  // Internal Status Flags (Local to a_clk)
  reg                   a_full_int;
  reg                   a_empty_int;

  // ---------------------------------------------------------------------------
  // Side B Logic (Clock: b_clk)
  // ---------------------------------------------------------------------------

  // State for pointer transfer to Side A
  reg [GRANT_WIDTH-1:0] b_ptr_to_a;
  reg                   b_ptr_to_a_valid;
  reg                   b_ptr_to_a_ack;

  // State for pointer transfer from Side A
  reg [GRANT_WIDTH-1:0] a_ptr_from_b;
  reg                   a_ptr_from_b_valid;
  reg                   a_ptr_from_b_ack;

  // Reset Done Flags (Crossed)
  // Note: b_rst_done is driven by b side, read by a side.
  // a_rst_done is driven by a side, read by b side.

  // Internal Pointers (Local to b_clk)
  reg [ASIZE-1:0]       b_wptr;
  reg [ASIZE-1:0]       b_rptr;
  reg                   b_wptr_valid;
  reg                   b_rptr_valid;

  // Internal Status Flags (Local to b_clk)
  reg                   b_full_int;
  reg                   b_empty_int;

  // ---------------------------------------------------------------------------
  // RAM Interface Generation
  // ---------------------------------------------------------------------------

  // Side A RAM Interface (Driven by a_clk)
  assign o_ram_a_clk = a_clk;
  assign o_ram_a_wdata = (a_dir) ? a_wdata : b_wdata;
  assign o_ram_a_addr = (a_dir) ? a_wptr : b_wptr;
  assign o_ram_a_winc = (a_dir) ? a_winc : b_winc;
  assign o_ram_a_rinc = (a_dir) ? a_rinc : b_rinc;
  // Read data for Side A comes from the external input
  assign a_rdata = i_ram_a_rdata;

  // Side B RAM Interface (Driven by b_clk)
  assign o_ram_b_clk = b_clk;
  assign o_ram_b_wdata = (b_dir) ? b_wdata : a_wdata;
  assign o_ram_b_addr = (b_dir) ? b_wptr : a_wptr;
  assign o_ram_b_winc = (b_dir) ? b_winc : a_winc;
  assign o_ram_b_rinc = (b_dir) ? b_rinc : a_rinc;
  // Read data for Side B comes from the external input
  assign b_rdata = i_ram_b_rdata;

  // ---------------------------------------------------------------------------
  // Pointer Transfer Logic: A -> B
  // ---------------------------------------------------------------------------

  // 1. Prepare the pointer to send to B
  //    We send the current local write pointer when writing, or read pointer when reading.
  //    Actually, for a bidirectional FIFO, we need to send the pointer that represents
  //    the boundary of the data available to the other side.
  //    Standard approach: Send Write Ptr when writing, Read Ptr when reading.
  //    However, to simplify the handshake, we will always send the "Current Write Ptr"
  //    when the local side wants to update the other side's view of the write position,
  //    and "Current Read Ptr" when updating the read position.
  //    To make it robust, we send the pointer corresponding to the operation that
  //    changes the data availability.
  //    Let's define:
  //    - When A writes: A sends its Write Ptr to B.
  //    - When A reads: A sends its Read Ptr to B.

  // Generate the snapshot to send to B
  always @(posedge a_clk or negedge a_rst_n) begin
    if (!a_rst_n) begin
      a_ptr_to_b <= '0;
      a_ptr_to_b_valid <= 1'b0;
    end else begin
      if (a_winc) begin
        // Sending Write Ptr
        a_ptr_to_b <= {a_wptr, 1'b1};
        a_ptr_to_b_valid <= 1'b1;
      end else if (a_rinc) begin
        // Sending Read Ptr
        a_ptr_to_b <= {a_rptr, 1'b1};
        a_ptr_to_b_valid <= 1'b1;
      end else begin
        a_ptr_to_b_valid <= 1'b0;
      end
    end
  end

  // 2. Receive pointer from B (Handshake)
  //    B sends {b_ptr, 1'b1} on b_ptr_to_a_valid.
  //    A acknowledges when it has latched the value.
  always @(posedge a_clk or negedge a_rst_n) begin
    if (!a_rst_n) begin
      b_ptr_from_a <= '0;
      b_ptr_from_a_valid <= 1'b0;
      b_ptr_from_a_ack <= 1'b0;
    end else begin
      if (a_ptr_to_b_ack) begin
        b_ptr_from_a_ack <= 1'b0;
        b_ptr_from_a_valid <= 1'b0;
      end else if (b_ptr_to_a_valid) begin
        b_ptr_from_a <= b_ptr_to_a;
        b_ptr_from_a_valid <= 1'b1;
        // Acknowledge immediately after latching to keep pipeline moving
        // (Single cycle latency is acceptable for pointer transfer)
        b_ptr_from_a_ack <= 1'b1;
      end
    end
  end

