  // Pointer Transfer Logic: B -> A
  // ---------------------------------------------------------------------------

  // 1. Prepare the pointer to send to A
  always @(posedge b_clk or negedge b_rst_n) begin
    if (!b_rst_n) begin
      b_ptr_to_a <= '0;
      b_ptr_to_a_valid <= 1'b0;
    end else begin
      if (b_winc) begin
        b_ptr_to_a <= {b_wptr, 1'b1};
        b_ptr_to_a_valid <= 1'b1;
      end else if (b_rinc) begin
        b_ptr_to_a <= {b_rptr, 1'b1};
        b_ptr_to_a_valid <= 1'b1;
      end else begin
        b_ptr_to_a_valid <= 1'b0;
      end
    end
  end

